local Players=game:GetService("Players");local r=game:GetService("ReplicatedStorage"):WaitForChild("Remotes",10);if not r then return end;local updated=r:WaitForChild("QuestUpdated")::RemoteEvent;local claim=r:WaitForChild("ClaimQuest")::RemoteEvent;local gui=Instance.new("ScreenGui");gui.Name="QuestGui";gui.ResetOnSpawn=false;gui.Parent=Players.LocalPlayer.PlayerGui;local f=Instance.new("Frame");f.Position=UDim2.fromScale(.72,.2);f.Size=UDim2.fromScale(.26,.38);f.BackgroundColor3=Color3.fromRGB(35,45,60);f.Visible=false;f.Parent=gui;local list=Instance.new("UIListLayout");list.Parent=f;updated.OnClientEvent:Connect(function(d)for _,x in f:GetChildren()do if x:IsA("TextButton")then x:Destroy()end end;for _,q in d.quests do local b=Instance.new("TextButton");b.Size=UDim2.fromScale(1,.25);b.Text=string.format("%s %d/%d\n+%d Coins%s",q.name,q.progress,q.target,q.reward,q.claimed and" 已領取"or"");b.TextWrapped=true;b.TextScaled=true;b.Parent=f;b.Activated:Connect(function()claim:FireServer(q.id)end)end;f.Visible=true end)
